import {editableQuestions} from './quiz-authoring.mjs';
import {ADDITIONAL_ACTIVITIES} from './quiz-additional-model.mjs';
import {QUESTION_LABELS,DISPLAY_TYPES} from './quiz-model.mjs';
import {questionImage} from './quiz-media.mjs';
import {createQuizWidgets} from './quiz-widgets.mjs';
export function createQuizUI({e,api,ui,link,field,area,btn,option,getWorkflow}){
 let draft=null,currentAssignment=null,currentSubmission=null;
 const widgets=createQuizWidgets({e,option,api});
 const newQuestion=()=>({id:crypto.randomUUID(),type:'choice',prompt:'',points:1,required:true,options:['',''],correct:0});
 const groups={ 'Choice & text':['choice','checkboxes','dropdown','truefalse','short','paragraph'], 'Maths & interactive':['math','missing','dragwords','matching','ranking'], 'Survey & grids':['grid','checkboxgrid','likert','scale','rating','nps'], 'Dates & uploads':['date','datetime','time','duration','file'], 'Sections & images':['section','image']};
 const types=selected=>(ADDITIONAL_ACTIVITIES[selected]?option(selected,QUESTION_LABELS[selected],selected):['video','external'].includes(selected)?option(selected,QUESTION_LABELS[selected],selected):'')+Object.entries(groups).map(([label,keys])=>`<optgroup label="${label}">${keys.map(v=>option(v,QUESTION_LABELS[v],selected)).join('')}</optgroup>`).join('');
 function questionEditor(q,i){const display=DISPLAY_TYPES.includes(q.type);return `<fieldset class="vle-quiz-question" data-quiz-question="${i}"><legend><span draggable="true" data-question-drag="${i}" class="quiz-drag-handle" title="Drag to reorder">⠿</span> Question ${i+1}</legend><div class="vle-form-grid"><label class="vle-field">Question type<select data-question-field="type">${types(q.type)}</select></label><label class="vle-field">Points <small>0 = unscored</small><input data-question-field="points" type="number" step="0.5" min="0" max="100" value="${display?0:q.points}" ${display?'readonly':''} required></label></div><label class="vle-field">${display?'Heading / description':'Question'}<textarea data-question-field="prompt" maxlength="2000" required>${e(q.prompt)}</textarea></label><label class="vle-field">Learning objective (optional)<input data-question-field="objective" maxlength="160" value="${e(q.objective||'')}" placeholder="e.g. Add fractions with unlike denominators"></label>${widgets.config(q,i)}${widgets.common(q)}<div class="vle-question-actions"><label><input type="checkbox" data-question-field="required" ${q.required&&!display?'checked':''} ${display?'disabled':''}> Required</label><div><button type="button" class="text-button" data-quiz-move="${i}" data-direction="-1" ${i===0?'disabled':''}>↑ Move up</button> <button type="button" class="text-button" data-quiz-move="${i}" data-direction="1" ${i===draft.questions.length-1?'disabled':''}>↓ Move down</button> <button type="button" class="text-button" data-quiz-duplicate="${i}">Duplicate</button> <button type="button" class="text-button" data-quiz-remove="${i}" ${draft.questions.length===1?'disabled':''}>Remove</button></div></div></fieldset>`;}
 function readQuestions(form){return [...form.querySelectorAll('[data-quiz-question]')].map((el,i)=>{const previous=draft?.questions[i]||{},type=el.querySelector('[data-question-field="type"]').value;let q=widgets.readConfig(el,{...previous,type});q={...q,mediaOpen:el.querySelector('.quiz-media-settings').open,id:previous.id||'q'+(i+1),prompt:el.querySelector('[data-question-field="prompt"]').value,objective:el.querySelector('[data-question-field="objective"]').value,points:Number(el.querySelector('[data-question-field="points"]').value),required:el.querySelector('[data-question-field="required"]').checked,description:el.querySelector('[data-q="description"]').value,formula:el.querySelector('[data-q="formula"]').value,feedback:{correct:el.querySelector('[data-q="feedbackCorrect"]').value,incorrect:el.querySelector('[data-q="feedbackIncorrect"]').value}};if(q.image)q.image={...q.image,alt:el.querySelector('[data-q="imageAlt"]').value};return q;});}
 async function editorPage(params){if(ui.actor().role==='student')throw Error('Only teachers can create quizzes.');const id=params.get('quizEditor');let a;if(id==='new'){const room=await api('room?id='+encodeURIComponent(params.get('class')));a={classId:room.class.id,title:'',topic:'Quizzes',description:'',due:'',learning:{unitId:params.get('unit')||''},questions:[newQuestion()]};}else{a=(await api('assignment?id='+encodeURIComponent(id))).assignment;if(a.kind!=='quiz'||a.status!=='draft')throw Error('Only draft quizzes can be edited.');}draft=structuredClone(a);const room=await api('room?id='+encodeURIComponent(a.classId));return `<div class="vle-breadcrumb">${link('← Classwork',{class:a.classId,tab:'classwork'})}</div><div class="vle-quiz-editor-heading"><span class="vle-quiz-label">QUESTION LIBRARY</span><h2>${a.id?'Edit draft quiz':'Create a quiz or form'}</h2><p>${Object.keys(QUESTION_LABELS).length} question and content types · Core question types plus the Additional activity menu.</p></div><form data-vle="${a.id?'quiz-update':'quiz-create'}" id="vle-quiz-editor"><input type="hidden" name="classId" value="${e(a.classId)}">${a.id?`<input type="hidden" name="id" value="${e(a.id)}"><input type="hidden" name="expectedRevision" value="${a.revision}">`:''}<section class="vle-panel"><div class="vle-form-grid">${field('Quiz / form title','title','required maxlength="160"',a.title)}${field('Topic','topic','maxlength="100"',a.topic)}${field('Due date','due','type="date"',a.due||'')}<div class="vle-quiz-total">Total: <strong id="vle-quiz-total">${a.questions.reduce((n,q)=>n+q.points,0)}</strong> points</div></div>${area('Instructions','description',a.description,'maxlength="10000"')}</section>${getWorkflow().optionsEditor(a,room.people,room.units)}<section class="vle-panel quiz-additional-panel"><button type="button" class="btn" id="vle-additional" aria-expanded="false" aria-controls="vle-additional-menu">Additional ▾</button> <button type="button" class="btn" id="vle-question-bank">Bank ▾</button><span class="vle-note"> More activities for primary and secondary</span><div id="vle-additional-menu" hidden><p>Choose an activity to add it to this assessment. Everything runs inside Classroom.</p><div class="quiz-additional-grid">${Object.entries(ADDITIONAL_ACTIVITIES).map(([type,[title,description]])=>'<button type="button" data-additional-type="'+type+'"><strong>'+e(title)+'</strong><span>'+e(description)+'</span></button>').join('')}</div></div></section><section class="vle-panel" id="vle-bank-panel" hidden><h3>My question banks</h3><p>Save questions from a saved quiz, then reuse them here.</p><div id="vle-bank-items"></div></section><div id="vle-quiz-questions">${a.questions.map(questionEditor).join('')}</div><div class="vle-quiz-toolbar"><button type="button" class="btn" id="vle-quiz-add">＋ Add question / section</button><span>Up to 40 items · 0-point forms collect responses without MIS marks.</span></div><div class="vle-quiz-save"><span>Teacher chooses which scores to add to the MIS.</span><div class="vle-actions">${btn('Save draft','draft')}${btn('Assign quiz / form','publish','primary')}</div></div></form>`;}
 function bindEditor(root){widgets.bindStudent(root);const form=root.querySelector('#vle-quiz-editor');if(!form)return;const questions=form.querySelector('#vle-quiz-questions');let uploading=0,dragIndex=null;const update=()=>{form.querySelector('#vle-quiz-total').textContent=readQuestions(form).reduce((n,q)=>n+q.points,0);};const paint=()=>{questions.innerHTML=draft.questions.map(questionEditor).join('');update();ui.dirty(true);};
  form.querySelector('#vle-question-bank').addEventListener('click',async()=>{const box=form.querySelector('#vle-bank-panel');box.hidden=!box.hidden;if(box.hidden)return;try{const bank=await api('library'),items=bank.items.filter(x=>x.kind==='question');box.querySelector('#vle-bank-items').innerHTML=items.map(x=>'<button type="button" class="learning-bank-item" data-bank-id="'+e(x.id)+'"><strong>'+e(x.title)+'</strong><small>'+e(x.subject)+' · '+e(x.topic)+'</small></button>').join('')||'<p>No bank questions yet. Save a quiz, open it and choose Save question to bank.</p>';box.querySelectorAll('[data-bank-id]').forEach(b=>b.addEventListener('click',()=>{draft.questions=readQuestions(form);if(draft.questions.length>=40){ui.toast('A quiz can have up to 40 items.');return;}const q=editableQuestions(items.find(x=>x.id===b.dataset.bankId).content.questions)[0];q.id=crypto.randomUUID();if(draft.questions.length===1&&!draft.questions[0].prompt&&!draft.questions[0].options?.some(Boolean))draft.questions=[q];else draft.questions.push(q);box.hidden=true;paint();}));}catch(error){ui.toast(error.message);}});
  form.querySelector('#vle-additional').addEventListener('click',ev=>{const b=ev.currentTarget,menu=form.querySelector('#vle-additional-menu');menu.hidden=!menu.hidden;b.setAttribute('aria-expanded',String(!menu.hidden));});
  form.querySelectorAll('[data-additional-type]').forEach(b=>b.addEventListener('click',()=>{draft.questions=readQuestions(form);if(draft.questions.length>=40){ui.toast('A form can have up to 40 items.');return;}const q={...newQuestion(),type:b.dataset.additionalType,correct:undefined};if(['labels','hotspot'].includes(q.type))q.mediaOpen=true;if(draft.questions.length===1&&!draft.questions[0].prompt&&!draft.questions[0].options?.some(Boolean))draft.questions=[q];else draft.questions.push(q);form.querySelector('#vle-additional-menu').hidden=true;form.querySelector('#vle-additional').setAttribute('aria-expanded','false');paint();questions.lastElementChild.scrollIntoView({block:'nearest'});}));
  questions.addEventListener('change',async ev=>{const el=ev.target,index=Number(el.closest('[data-quiz-question]')?.dataset.quizQuestion);if(el.matches('[data-question-image],[data-option-image],[data-question-audio]')){draft.questions=readQuestions(form);if(!el.files.length)return;const imageQuestionId=draft.questions[index].id;uploading++;form.querySelectorAll('button[type=submit]').forEach(b=>b.disabled=true);try{const [file]=await widgets.filesFromInput(el),image=el.hasAttribute('data-question-audio')?file:questionImage({...file,alt:el.files[0].name});draft.questions=readQuestions(form);const target=draft.questions.find(q=>q.id===imageQuestionId);if(!target)return;target.mediaOpen=true;if(el.hasAttribute('data-question-audio')){target.audio=image;}else if(el.hasAttribute('data-option-image')){target.optionImages??={};target.optionImages[el.dataset.optionImage]=image;}else target.image=image;paint();}catch(error){ui.toast(error.message);}finally{uploading--;if(!uploading)form.querySelectorAll('button[type=submit]').forEach(b=>b.disabled=false);}return;}
   if(el.dataset.questionField!=='type'){if(el.dataset.questionField==='points')update();return;}const old=draft.questions[index],type=el.value;el.value=old.type;draft.questions=readQuestions(form);const q=draft.questions[index];q.type=type;q.correct=type==='checkboxes'?[]:0;q.options=type==='truefalse'?['True','False']:['',''];q.acceptedAnswers=[];q.rows=[];q.pairs=[];q.passage='';q.blankAnswers=undefined;q.optionImages={};if(DISPLAY_TYPES.includes(type)||['likert','scale','rating','nps','date','datetime','time','duration'].includes(type))q.points=0;else if(!q.points)q.points=1;q.required=!DISPLAY_TYPES.includes(type);if(['ranking','matching','grid','checkboxgrid','likert'].includes(type))delete q.correct;paint();});
  questions.addEventListener('click',ev=>{const img=ev.target.closest('.quiz-question-image img');if(!img)return;const row=img.closest('[data-quiz-question]'),q=draft.questions[Number(row.dataset.quizQuestion)];if(!['labels','hotspot'].includes(q.type))return;const b=img.getBoundingClientRect(),x=((ev.clientX-b.left)/b.width*100).toFixed(1),y=((ev.clientY-b.top)/b.height*100).toFixed(1),field=row.querySelector('[data-q="'+(q.type==='labels'?'targets':'hotspots')+'"]');field.value+=(field.value?'\n':'')+(q.type==='labels'?'Label '+(field.value.split('\n').filter(Boolean).length+1)+' => '+x+', '+y:x+', '+y+', 8');field.dispatchEvent(new Event('input',{bubbles:true}));});
  questions.addEventListener('input',ev=>{if(ev.target.dataset.questionField==='points')update();});
  form.addEventListener('click',ev=>{const b=ev.target.closest('[data-quiz-add-option],[data-quiz-remove-option],[data-quiz-remove],[data-quiz-move],[data-quiz-duplicate],[data-remove-question-image],[data-remove-option-image],#vle-quiz-add');if(!b)return;draft.questions=readQuestions(form);if(b.id==='vle-quiz-add'||b.dataset.quizDuplicate!==undefined){if(draft.questions.length>=40){ui.toast('A form can have up to 40 items.');return;}if(b.id==='vle-quiz-add')draft.questions.push(newQuestion());else{const i=Number(b.dataset.quizDuplicate),q=structuredClone(draft.questions[i]);q.id=crypto.randomUUID();draft.questions.splice(i+1,0,q);}}else if(b.hasAttribute('data-remove-question-image'))delete draft.questions[Number(b.closest('[data-quiz-question]').dataset.quizQuestion)].image;else if(b.hasAttribute('data-remove-option-image'))delete draft.questions[Number(b.closest('[data-quiz-question]').dataset.quizQuestion)].optionImages[b.dataset.removeOptionImage];else if(b.dataset.quizAddOption!==undefined)draft.questions[Number(b.dataset.quizAddOption)].options.push('');else if(b.dataset.quizRemoveOption!==undefined){const q=draft.questions[Number(b.dataset.quizRemoveOption)],j=Number(b.dataset.optionIndex);q.options.splice(j,1);q.correct=Array.isArray(q.correct)?q.correct.filter(x=>x!==j).map(x=>x>j?x-1:x):q.correct===j?undefined:q.correct>j?q.correct-1:q.correct;q.optionImages=Object.fromEntries(Object.entries(q.optionImages||{}).filter(([key])=>Number(key)!==j).map(([key,v])=>[Number(key)>j?Number(key)-1:key,v]));}else if(b.dataset.quizRemove!==undefined)draft.questions.splice(Number(b.dataset.quizRemove),1);else{const i=Number(b.dataset.quizMove),j=i+Number(b.dataset.direction);[draft.questions[i],draft.questions[j]]=[draft.questions[j],draft.questions[i]];}paint();});
  questions.addEventListener('dragstart',ev=>{const handle=ev.target.closest('[data-question-drag]');if(!handle)return;dragIndex=Number(handle.dataset.questionDrag);ev.dataTransfer.setData('text/plain','quiz-question');});questions.addEventListener('dragover',ev=>{if(dragIndex!==null&&ev.target.closest('[data-quiz-question]'))ev.preventDefault();});questions.addEventListener('drop',ev=>{const target=ev.target.closest('[data-quiz-question]');if(dragIndex===null||!target)return;ev.preventDefault();draft.questions=readQuestions(form);const to=Number(target.dataset.quizQuestion),[moved]=draft.questions.splice(dragIndex,1);draft.questions.splice(to,0,moved);dragIndex=null;paint();});
 }
 function studentForm(a,s){currentAssignment=a;currentSubmission=s;const locked=!!s?.turnedInAt&&!s.returnedAt,feedback=s?.returnedAt?`<div class="vle-feedback"><strong>${a.maximum>0?s.mark+'/'+a.maximum+' · '+Math.round(s.mark/a.maximum*100)+'%':'Response returned'}</strong><p class="vle-prose">${e(s.feedback||'Your teacher returned this response.')}</p></div>`:'';return `<section class="vle-panel"><h3>Your ${a.maximum>0?'quiz':'form'} <span class="vle-status">${s?.returnedAt?'Returned':s?.turnedInAt?'Turned in':s?'Draft':'Ready to start'}</span></h3>${feedback}<p class="vle-note">Your teacher reviews scored answers before returning them. * = required. Use keyboard controls as an alternative to dragging.</p><form data-vle="quiz-submit"><input type="hidden" name="id" value="${e(a.id)}"><input type="hidden" name="expectedRevision" value="${s?.revision||0}">${a.questions.map((q,i)=>`<fieldset class="vle-quiz-question ${DISPLAY_TYPES.includes(q.type)?'quiz-content-block':''}" data-quiz-answer="${q.id}" data-question-type="${q.type}"><legend>${i+1}. ${widgets.mathText(q.prompt)}${q.required?' *':''} <small>${q.points? q.points+' points':'Unscored'}</small></legend>${q.description?'<p class="vle-prose">'+widgets.mathText(q.description)+'</p>':''}${['labels','hotspot'].includes(q.type)?'':widgets.imageHTML(q.image)}${q.formula?'<div class="quiz-math-preview">'+widgets.mathHTML(q.formula)+'</div>':''}${widgets.studentWidget(q,s?.answers?.[q.id],locked)}${s?.returnedAt&&q.points>0?`<p class="vle-question-result">Awarded ${s.questionMarks?.[q.id]??'—'} / ${q.points}${s.questionComments?.[q.id]?'<br>'+e(s.questionComments[q.id]):s.questionFeedback?.[q.id]?'<br>'+e(s.questionFeedback[q.id]):''}</p>`:''}</fieldset>`).join('')}${!locked?getWorkflow().reflection(s)+getWorkflow().saveStatus():''}<div class="vle-actions">${locked?btn('Unsubmit to edit','unsubmit'):btn('Save answers','draft')+btn(s?.returnedAt?'Resubmit':'Turn in '+(a.maximum>0?'quiz':'form'),'submit','primary')}</div></form></section>`;}
 async function readAnswers(form){const pairs=await Promise.all([...form.querySelectorAll('[data-quiz-answer]')].map(async el=>{const q=currentAssignment.questions.find(q=>q.id===el.dataset.quizAnswer);return[q.id,await widgets.readAnswer(el,q,currentSubmission?.answers?.[q.id])];}));return Object.fromEntries(pairs);}
 const downloads=[];
 function answerHTML(q,v){if(q.type==='drawing')return widgets.imageHTML(v?.image)+'<p class="vle-prose">'+e(v?.description||'')+'</p>';if(q.type==='spoken')return widgets.extra.audioHTML(v?.[0]);if(q.type==='file')return(v||[]).map(f=>{const bytes=Uint8Array.from(atob(f.data),c=>c.charCodeAt(0)),url=URL.createObjectURL(new Blob([bytes],{type:'application/octet-stream'}));downloads.push(url);return '<a class="vle-file" href="'+url+'" download="'+e(f.name)+'">Download '+e(f.name)+' ↓</a>';}).join('');return '<p class="vle-prose">'+widgets.mathText(widgets.answerText(q,v)||'No response')+'</p>';}
 function review(a,s){return `<div class="vle-quiz-review-summary"><strong>${s.autoTotal??0} points automatically marked</strong><span>${s.returnedAt?'Reviewed and returned.':s.needsReview?'Teacher marking is needed.':'Review suggested automatic marks before returning.'}</span></div><button type="button" class="text-button" data-review-expand>Expand all answers</button>${a.questions.map((q,i)=>`<details class="learning-review-question" ${(s.questionMarks?.[q.id]??s.autoMarks?.[q.id])===null||s.questionMarks?.[q.id]===undefined&&s.autoMarks?.[q.id]===undefined?'open':''}><summary><strong>${i+1}. ${widgets.mathText(q.prompt)}</strong><span>${s.questionMarks?.[q.id]??s.autoMarks?.[q.id]??'Needs marking'} / ${q.points}</span></summary><fieldset class="vle-quiz-question"><legend>${i+1}. ${widgets.mathText(q.prompt)}</legend><small>${e(QUESTION_LABELS[q.type])} · ${q.points} points</small>${widgets.imageHTML(q.image)}${q.formula?'<div class="quiz-math-preview">'+widgets.mathHTML(q.formula)+'</div>':''}${answerHTML(q,s.answers?.[q.id])}${keyHTML(q)}<button type="button" class="text-button" data-save-bank-question="${q.id}" data-assignment="${e(a.id)}">Save question to bank</button>${q.points>0?`<label class="vle-field">Awarded mark<input data-quiz-mark="${q.id}" type="number" min="0" max="${q.points}" step="any" required value="${s.questionMarks?.[q.id]??s.autoMarks?.[q.id]??''}"></label>`:`<input type="hidden" data-quiz-mark="${q.id}" value="0"><small>Unscored item</small>`}<label class="vle-field">Feedback for this answer<textarea data-question-comment="${q.id}" maxlength="2000">${e(s.questionComments?.[q.id]||'')}</textarea></label></fieldset></details>`).join('')}`;}
 function keyHTML(q){if(q.type==='hotspot')return '<p>Correct areas: '+e(q.correct.map(p=>'('+p.x+'%, '+p.y+'%), radius '+p.radius+'%').join('; '))+'</p>';if(q.type==='crossword')return '<p>Answer key: '+e(q.correct.join(' / '))+'</p>';if(q.type==='memory')return '<p>Pairs: '+e(q.cards.flatMap((t,i)=>q.correct.indexOf(q.correct[i])===i?[t+' ↔ '+q.cards[q.correct.lastIndexOf(q.correct[i])]]:[]).join('; '))+'</p>';let key=q.correct!==undefined&&q.correct!==null?widgets.answerText(q,q.correct):q.blankAnswers?q.blankAnswers.map(a=>a.join(' / ')).join('; '):q.type==='math'&&q.mathMode==='numeric'?String(q.numericKey)+' ± '+q.tolerance:q.acceptedAnswers?.length?q.acceptedAnswers.join(' / '):q.guidance||'';return key?'<p class="vle-answer-key-text">Answer key / guidance: '+widgets.mathText(key)+'</p>':'';}
 const readReview=form=>Object.fromEntries([...form.querySelectorAll('[data-quiz-mark]')].map(el=>[el.dataset.quizMark,el.value===''?null:Number(el.value)]));
 function keyPreview(a){return '<details class="vle-panel"><summary>View questions, images & answer keys</summary>'+a.questions.map((q,i)=>'<div class="vle-key-preview"><strong>'+(i+1)+'. '+widgets.mathText(q.prompt)+'</strong><small>'+e(QUESTION_LABELS[q.type])+' · '+q.points+' points</small>'+widgets.imageHTML(q.image)+(q.formula?widgets.mathHTML(q.formula):'')+keyHTML(q)+'<button type="button" class="text-button" data-save-bank-question="'+q.id+'" data-assignment="'+e(a.id)+'">Save question to bank</button></div>').join('')+'</details>';}
 function release(){widgets.extra.release();for(const url of downloads.splice(0))URL.revokeObjectURL(url);}
 return{editorPage,bindEditor,readQuestions,studentForm,readAnswers,review,readReview,keyPreview,release};
}
